import org.mockito.Mockito.*
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.*;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import com.google.gson.stream.JsonWriter;
import java.io.IOException;
import java.io.Writer;
import java.util.ArrayList;
import java.util.List;

public class JsonTreeWriterTest{
private JsonTreeWriter jsonTreeWriter;
  private JsonTreeWriter jsonTreeWriterNotLenient;

  @Before 
  public void init(){
    jsonTreeWriter = new JsonTreeWriter();
    JsonTreeWriter.setLenient(true);
    jsonTreeWriterNotLenient = new JsonTreeWriter();
    JsonTreeWriter.setLenient(false);
  }

  @After
  public void tearDown() throws Exception {
  }

  @Test
  public void testValueNull() throws IOException {
    JsonWriter writer = jsonTreeWriter.value(null);
    assertThat(writer, notNullValue());
    JsonElement product = jsonTreeWriter.get();
    assertThat(product, instanceOf(JsonNull.class));
  }

  @Test
  public void testValueNotNull() throws IOException {
    Number value = 123;
    JsonWriter writer = jsonTreeWriter.value(value);
    assertThat(writer, notNullValue());
    JsonElement product = jsonTreeWriter.get();
    assertThat(product, instanceOf(JsonPrimitive.class));
    JsonPrimitive jsonPrimitive = (JsonPrimitive) product;
    assertThat(jsonPrimitive.getAsNumber().doubleValue(), equalTo(123.0));
  }

  @Test(expected = IllegalArgumentException.class)
  public void testValueNotLenientInfinite() throws IOException {
    jsonTreeWriterNotLenient.value(Double.POSITIVE_INFINITY);
  }

  @Test(expected = IllegalArgumentException.class)
  public void testValueNotLenientNaN() throws IOException {
    jsonTreeWriterNotLenient.value(Double.NaN);
  }

  @Test
  public void testValueLenientInfinite() throws IOException {
    JsonWriter writer = jsonTreeWriter.value(Double.POSITIVE_INFINITY);
    assertThat(writer, notNullValue());
    JsonElement product = jsonTreeWriter.get();
    assertThat(product, instanceOf(JsonPrimitive.class));
    JsonPrimitive jsonPrimitive = (JsonPrimitive) product;
    assertThat(jsonPrimitive.getAsNumber().doubleValue(), equalTo(Double.POSITIVE_INFINITY));
  }

  @Test
  public void testValueLenientNaN() throws IOException {
    JsonWriter writer = jsonTreeWriter.value(Double.NaN);
    assertThat(writer, notNullValue());
    JsonElement product = jsonTreeWriter.get();
    assertThat(product, instanceOf(JsonPrimitive.class));
    JsonPrimitive jsonPrimitive = (JsonPrimitive) product;
    assertThat(jsonPrimitive.getAsNumber().doubleValue(), equalTo(Double.NaN));
  }
}
